() => {
const D=window.D, toLab=window.toLab, de00=window.de00, WP=window.WP;
// targets: f-values (cube roots of normalized XYZ)
window.T = D.map(r=>{const [c,m,y,X,Y,Z]=r; return [window.fcube(X/WP[0]),window.fcube(Y/WP[1]),window.fcube(Z/WP[2])];});
window.LabT = D.map(r=>toLab(r[3],r[4],r[5]));

window.solve=function(A,b){ // normal equations with ridge
 const n=A[0].length, N=new Array(n).fill(0).map(()=>new Array(n+1).fill(0));
 for(let i=0;i<A.length;i++){for(let j=0;j<n;j++){for(let k=0;k<n;k++)N[j][k]+=A[i][j]*A[i][k];N[j][n]+=A[i][j]*b[i];}}
 for(let j=0;j<n;j++)N[j][j]+=1e-10;
 for(let col=0;col<n;col++){
  let p=col; for(let r=col+1;r<n;r++) if(Math.abs(N[r][col])>Math.abs(N[p][col])) p=r;
  const tmp=N[col];N[col]=N[p];N[p]=tmp;
  const pv=N[col][col];
  for(let k=col;k<=n;k++)N[col][k]/=pv;
  for(let r=0;r<n;r++){ if(r===col)continue; const f=N[r][col]; if(f===0)continue; for(let k=col;k<=n;k++)N[r][k]-=f*N[col][k]; }
 }
 return N.map(r=>r[n]);
};

window.stats=function(predXYZ){
 const ds=predXYZ.map((p,i)=>de00(window.LabT[i], toLab(p[0],p[1],p[2])));
 ds.sort;
 const mean=ds.reduce((a,b)=>a+b,0)/ds.length;
 const max=Math.max(...ds);
 const sorted=[...ds].sort((a,b)=>a-b);
 return {mean:+mean.toFixed(4), max:+max.toFixed(4), p95:+sorted[Math.floor(0.95*ds.length)].toFixed(4)};
};

window.fitBasis=function(basisFn){
 const A=D.map(r=>basisFn(r[0]/100,r[1]/100,r[2]/100));
 const coefs=[0,1,2].map(k=>window.solve(A,window.T.map(t=>t[k])));
 const pred=D.map((r,i)=>{
   const a=A[i];
   return [0,1,2].map(k=>{let s=0;for(let j=0;j<a.length;j++)s+=a[j]*coefs[k][j];return WP[k]*Math.pow(Math.max(s,0.01),3);});
 });
 return {coefs, stats:window.stats(pred), nterms:A[0].length};
};

// Basis 1: Demichel (Neugebauer) 8 terms
const dem=(c,m,y)=>[(1-c)*(1-m)*(1-y), c*(1-m)*(1-y), (1-c)*m*(1-y), (1-c)*(1-m)*y, c*m*(1-y), c*(1-m)*y, (1-c)*m*y, c*m*y];
// Basis 2: full cubic polynomial (20 terms)
const cubic=(c,m,y)=>{const o=[];for(let i=0;i<=3;i++)for(let j=0;j<=3-i;j++)for(let k=0;k<=3-i-j;k++)o.push(Math.pow(c,i)*Math.pow(m,j)*Math.pow(y,k));return o;};
// Basis 3: quadratic (10 terms)
const quad=(c,m,y)=>{const o=[];for(let i=0;i<=2;i++)for(let j=0;j<=2-i;j++)for(let k=0;k<=2-i-j;k++)o.push(Math.pow(c,i)*Math.pow(m,j)*Math.pow(y,k));return o;};
window.dem=dem; window.cubic=cubic; window.quad=quad;
return {
 demichel: window.fitBasis(dem).stats,
 quad: window.fitBasis(quad).stats,
 cubic: window.fitBasis(cubic).stats
};
}

