() => {
const D=window.D, WP=window.WP, toLab=window.toLab, de00=window.de00;
function mkBasis(maxEach, maxTot){ return (c,m,y)=>{const o=[];for(let i=0;i<=maxEach;i++)for(let j=0;j<=maxEach;j++)for(let k=0;k<=maxEach;k++){if(i+j+k<=maxTot)o.push(Math.pow(c,i)*Math.pow(m,j)*Math.pow(y,k));}return o;};}
window.mkBasis=mkBasis;
function loo(basisFn){
  const A=D.map(r=>basisFn(r[0]/100,r[1]/100,r[2]/100));
  const n=A[0].length; const ds=[];
  for(let out=0;out<D.length;out++){
    const Atr=A.filter((_,i)=>i!==out), Ttr=window.T.filter((_,i)=>i!==out);
    const coefs=[0,1,2].map(k=>window.solve(Atr,Ttr.map(t=>t[k])));
    const a=A[out];
    const p=[0,1,2].map(k=>{let s=0;for(let j=0;j<n;j++)s+=a[j]*coefs[k][j];return WP[k]*Math.pow(Math.max(s,0.01),3);});
    ds.push(de00(window.LabT[out], toLab(p[0],p[1],p[2])));
  }
  const mean=ds.reduce((a,b)=>a+b,0)/ds.length;
  return {looMean:+mean.toFixed(4), looMax:+Math.max(...ds).toFixed(4)};
}
const cands={
 'd3(20)': mkBasis(3,3),
 'd4e3(31)': mkBasis(3,4),
 'd5e3(37)': mkBasis(3,5),
 'd6e3(40)': mkBasis(3,6),
 'd7e3(43)': mkBasis(3,7),
 'd9e3(64)': mkBasis(3,9),
 'd4e2(19)': mkBasis(2,4),
 'd6e2(27)': mkBasis(2,6)
};
const out={};
for(const k in cands){ const f=window.fitBasis(cands[k]); out[k]={n:f.nterms, fit:f.stats, cv:loo(cands[k])}; }
return out;
}

