() => {
const D=window.D, WP=window.WP, toLab=window.toLab, de00=window.de00, A=window.A, LabT=window.LabT;
window.makeModel=function(Ss){
  const rows=Ss.map(S=>D.map((_,i)=>S.map(j=>A[i][j])));
  const sizes=Ss.map(S=>S.length);
  const off=[0,sizes[0],sizes[0]+sizes[1]];
  const npar=sizes[0]+sizes[1]+sizes[2];
  function resid(p){
    const out=new Float64Array(D.length);
    for(let i=0;i<D.length;i++){
      const xyz=[0,1,2].map(k=>{let s=0;const r=rows[k][i];for(let j=0;j<sizes[k];j++)s+=p[off[k]+j]*r[j];return WP[k]*Math.pow(Math.max(s,0.004),3);});
      out[i]=de00(LabT[i],toLab(xyz[0],xyz[1],xyz[2]));
    }
    return out;
  }
  return {rows,sizes,off,npar,resid};
};
window.lm=function(model,p0,iters,pw){
  pw=pw||2;
  let p=Float64Array.from(p0);
  const n=model.npar, N=D.length;
  const cost=(r)=>{let s=0;for(let i=0;i<N;i++)s+=Math.pow(r[i],pw);return s;};
  let r=model.resid(p), C=cost(r);
  let lam=1e-3;
  for(let it=0;it<iters;it++){
    // residual vector for GN: use w_i * r_i where weight makes sum r^pw -> weighted LS
    const w=new Float64Array(N);
    for(let i=0;i<N;i++) w[i]=Math.pow(Math.max(r[i],1e-6),(pw-2)/2);
    const J=[]; for(let i=0;i<N;i++)J.push(new Float64Array(n));
    for(let j=0;j<n;j++){
      const h=Math.max(1e-6,Math.abs(p[j])*1e-6);
      const pp=Float64Array.from(p); pp[j]+=h;
      const rp=model.resid(pp);
      for(let i=0;i<N;i++)J[i][j]=(rp[i]-r[i])/h;
    }
    // normal equations
    const H=[]; for(let a=0;a<n;a++)H.push(new Float64Array(n+1));
    for(let i=0;i<N;i++){const wi=w[i]*w[i];for(let a=0;a<n;a++){const ja=J[i][a]*wi;for(let b=0;b<n;b++)H[a][b]+=ja*J[i][b];H[a][n]-=ja*r[i];}}
    let improved=false;
    for(let t=0;t<12;t++){
      const M=H.map(row=>Float64Array.from(row));
      for(let a=0;a<n;a++)M[a][a]*=(1+lam), M[a][a]+=lam*1e-12;
      let ok=true;
      for(let col=0;col<n;col++){let pv0=col;for(let rr=col+1;rr<n;rr++)if(Math.abs(M[rr][col])>Math.abs(M[pv0][col]))pv0=rr;const tt=M[col];M[col]=M[pv0];M[pv0]=tt;const pv=M[col][col];if(!isFinite(pv)||Math.abs(pv)<1e-18){ok=false;break;}for(let q=col;q<=n;q++)M[col][q]/=pv;for(let rr=0;rr<n;rr++){if(rr===col)continue;const f=M[rr][col];if(f===0)continue;for(let q=col;q<=n;q++)M[rr][q]-=f*M[col][q];}}
      if(!ok){lam*=10;continue;}
      const pn=Float64Array.from(p); for(let a=0;a<n;a++)pn[a]+=M[a][n];
      const rn=model.resid(pn), Cn=cost(rn);
      if(isFinite(Cn)&&Cn<C){p=pn;r=rn;C=Cn;lam=Math.max(lam*0.3,1e-9);improved=true;break;}
      lam*=10;
    }
    if(!improved)break;
  }
  return {p,r,cost:C};
};
window.rstats=function(r){const a=Array.from(r);const mean=a.reduce((x,b)=>x+b,0)/a.length;return {mean:+mean.toFixed(4),max:+Math.max(...a).toFixed(4)};};
// test on 20-term and 32-term greedy selections
const res={};
for(const n of [20,32]){
  const Ss=[0,1,2].map(k=>window.greedySel[k].S.slice(0,n));
  const xs=Ss.map((S,k)=>window.solveSub(S,k));
  const p0=[].concat(...xs);
  const model=window.makeModel(Ss);
  const before=window.rstats(model.resid(p0));
  const fit=window.lm(model,p0,25,2);
  res['n'+n]={before, afterL2:window.rstats(fit.r)};
  window['fit'+n]={Ss,p:Array.from(fit.p)};
}
return res;
}

