const S=[[],[],[]];
const cur=[0,1,2].map(k=>window.yy[k]);
const hist=[];
for(let step=0; step<105; step++){
  let bestGain=-1,bk=-1,bi=-1,bs=null;
  for(let k=0;k<3;k++){
    for(let cand=0;cand<P;cand++){
      if(S[k].includes(cand))continue;
      const r=window.sseSub([...S[k],cand],k);
      if(!isFinite(r.sse))continue;
      const gain=W[k]*(cur[k]-r.sse);
      if(gain>bestGain){bestGain=gain;bk=k;bi=cand;bs=r.sse;}
    }
  }
  if(bk<0)break;
  S[bk].push(bi); cur[bk]=bs;
  hist.push({tot:step+1,sizes:[S[0].length,S[1].length,S[2].length]});
}
window.jointS=S.map(s=>s.slice());
window.jointHist=hist;
// evaluate dE00 at several total budgets by replaying
const out={};
for(const tot of [45,54,60,66,72,78,84,90,96,105]){
  const h=hist[tot-1];
  const Ss=[0,1,2].map(k=>window.jointS[k].slice(0,h.sizes[k]));
  const e=window.evalSel(Ss);
  out['tot'+tot]={sizes:h.sizes, fitMean:e.mean, fitMax:e.max, ...window.looSel(Ss)};
}
return out;
}

