// separable model: f_k = A_k*(1+a1 c+a2 c^2+a3 c^3)(1+b1 m+...)(1+d1 y+...)
function residSep(p){
 const out=new Float64Array(D.length);
 for(let i=0;i<D.length;i++){
  const [c,m,y]=CMY[i];
