() => {
const EXP=window.EXP, WP=window.WP, D=window.D, toLab=window.toLab, de00=window.de00, LabT=window.LabT;
const F=window.final['n32'];
const Ss=F.Ss, p=F.opts.P6;
const sizes=Ss.map(s=>s.length), off=[0,sizes[0],sizes[0]+sizes[1]];
// round coefficients
function build(dec){
 const lines=[];
 const coefSets=[];
 for(let k=0;k<3;k++){
   const terms=[]; const cs=[];
   for(let a=0;a<Ss[k].length;a++){
     const e=EXP[Ss[k][a]];
     let v=+p[off[k]+a].toFixed(dec);
     cs.push({e,v});
   }
   cs.sort((A,B)=>(A.e[0]+A.e[1]+A.e[2])-(B.e[0]+B.e[1]+B.e[2]) || A.e[0]-B.e[0] || A.e[1]-B.e[1] || A.e[2]-B.e[2]);
   coefSets.push(cs);
   for(const {e,v} of cs){
     let s=(v<0?' - ':' + ')+Math.abs(v).toFixed(dec);
     const names=['c','m','y'];
     for(let t=0;t<3;t++){ if(e[t]===1)s+='*('+names[t]+'/100)'; else if(e[t]>1)s+='*('+names[t]+'/100)**'+e[t]; }
     terms.push(s);
   }
   let expr=terms.join('').trim();
   if(expr.startsWith('+ '))expr=expr.slice(2);
   lines.push(WP[k].toFixed(3)+'*('+expr+')**3');
 }
 return {lines,coefSets};
}
window.buildFn=build;
function evalRounded(coefSets){
 const ds=D.map((r,i)=>{
  const c=r[0]/100,m=r[1]/100,y=r[2]/100;
  const xyz=[0,1,2].map(k=>{let s=0;for(const {e,v} of coefSets[k])s+=v*Math.pow(c,e[0])*Math.pow(m,e[1])*Math.pow(y,e[2]);return WP[k]*Math.pow(s,3);});
  return de00(LabT[i],toLab(xyz[0],xyz[1],xyz[2]));
 });
 return {mean:+(ds.reduce((a,b)=>a+b,0)/ds.length).toFixed(4),max:+Math.max(...ds).toFixed(4)};
}
const res={};
for(const dec of [4,5,6,7,8]){ const b=build(dec); res['dec'+dec]=evalRounded(b.coefSets); }
// sanity over full cube with dec=7
const b7=build(7);
let minf=1e9,maxf=-1e9;
for(let c=0;c<=1.0001;c+=0.02)for(let m=0;m<=1.0001;m+=0.02)for(let y=0;y<=1.0001;y+=0.02){
  for(let k=0;k<3;k++){let s=0;for(const {e,v} of b7.coefSets[k])s+=v*Math.pow(c,e[0])*Math.pow(m,e[1])*Math.pow(y,e[2]);if(s<minf)minf=s;if(s>maxf)maxf=s;}
}
window.built=b7;
return {rounding:res, cubeMinF:+minf.toFixed(4), cubeMaxF:+maxf.toFixed(4), lens:b7.lines.map(l=>l.length)};
}

